  'draft_voucher': {"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"LineInput":{"description":"Input for one journal line.\n\nDebit and credit are separate fields rather than a direction plus an amount, matching what the user sees on screen: a voucher has two columns. The cost is having to forbid filling both explicitly, see [`DomainError::BothSides`].","properties":{"account_code":{"description":"Account code, matching `account.code`.","type":"string"},"bank_account_id":{"default":null,"description":"Which bank account this line moves, matching `bank_account.id`. The cash position is derived from this field.","format":"int32","type":["integer","null"]},"credit":{"description":"Credit amount; `\"0\"` when unused. A string in JSON.","type":"string"},"debit":{"description":"Debit amount; `\"0\"` when unused. A string in JSON.","type":"string"},"dept_code":{"default":null,"description":"Which department carries this line, matching a department code in `dimension_value`. Department profit and loss is derived from this field, so a line left empty is reported as unattributed rather than spread over the others.","type":["string","null"]},"memo":{"default":null,"description":"Line memo, falling back to the voucher memo.","type":["string","null"]}},"required":["account_code","credit","debit"],"type":"object"}},"properties":{"date":{"description":"Voucher date (YYYY-MM-DD).","format":"date","type":"string"},"lines":{"description":"Journal lines. At least two, and debits must equal credits.","items":{"$ref":"#/definitions/LineInput"},"type":"array"},"memo":{"description":"Memo, one line written for a human reader.","type":"string"}},"required":["date","lines","memo"],"title":"DraftVoucherInput","type":"object"},
