  'create_ar_invoice': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"amount":{"default":null,"description":"Tax-inclusive total, which is what the customer owes. Amounts are strings in JSON. Give any one or two of `amount`, `net_amount` and `tax_amount`; the rest follow from the VAT rules in force on the issue date.","type":["string","null"]},"customer":{"description":"Customer name.","type":"string"},"due_on":{"description":"Due date.","format":"date","type":"string"},"invoice_no":{"description":"Receivable document number; it need not be an e-invoice track number.","type":"string"},"issued_on":{"default":null,"description":"Issue date. Defaults to today.","format":"date","type":["string","null"]},"memo":{"default":"","description":"Description.","type":"string"},"net_amount":{"default":null,"description":"Amount before tax, credited to the revenue account.","type":["string","null"]},"output_tax_account_code":{"default":"2211","description":"Output tax account, default 2211. The VAT return reads the period movement of this account.","type":"string"},"receivable_account_code":{"default":"1131","description":"Receivables control account, default 1131.","type":"string"},"revenue_account_code":{"description":"Credit revenue account.","type":"string"},"tax_amount":{"default":null,"description":"Output tax, credited to 2211. Send `0` for a zero-rated export or an exempt sale.","type":["string","null"]}},"required":["customer","due_on","invoice_no","revenue_account_code"],"title":"CreateArInvoiceInput","type":"object"},
