  'create_ap_bill': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"amount":{"default":null,"description":"Tax-inclusive total, which is what the supplier is owed. Amounts are strings in JSON. Give any one or two of `amount`, `net_amount` and `tax_amount`; the rest follow from the VAT rules in force on the bill date.","type":["string","null"]},"bill_no":{"description":"Supplier's bill number.","type":"string"},"billed_on":{"default":null,"description":"Bill date. Defaults to today.","format":"date","type":["string","null"]},"debit_account_code":{"description":"Debit account: what the bill bought. Any active, postable expense, inventory, prepayment or non-current asset account. Cash, receivables and the other two accounts of this voucher are rejected.","type":"string"},"due_on":{"description":"Due date.","format":"date","type":"string"},"input_tax_account_code":{"default":"1284","description":"Input tax account, default 1284. The VAT return reads the period movement of this account.","type":"string"},"memo":{"default":"","description":"Bill description.","type":"string"},"net_amount":{"default":null,"description":"Amount before tax, debited to the expense or asset account.","type":["string","null"]},"payable_account_code":{"default":"2101","description":"Payables control account, default 2101.","type":"string"},"tax_amount":{"default":null,"description":"Deductible input tax, debited to 1284. Send `0` for a receipt that carries no deductible tax.","type":["string","null"]},"vendor":{"description":"Supplier name.","type":"string"}},"required":["bill_no","debit_account_code","due_on","vendor"],"title":"CreateApBillInput","type":"object"},
