  'create_fixed_asset': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"accum_gl_code":{"default":"1602","description":"Accumulated depreciation account, default 1602.","type":"string"},"acquired_on":{"default":null,"description":"Acquisition date. Defaults to today. Depreciation starts in this month and the useful life table is read as of this date.","format":"date","type":["string","null"]},"category":{"description":"Which line of the useful life table applies. `list_fixed_assets` returns the categories in force with their years.","type":"string"},"code":{"default":null,"description":"Asset code. Left out, the next free `FA###` is taken.","type":["string","null"]},"cost":{"description":"Cost before tax. This is the depreciable base and the debit to the asset account. A string in JSON.","type":"string"},"dept_code":{"default":null,"description":"Department carrying the asset, so its cost reaches departmental profit and loss.","type":["string","null"]},"gl_code":{"default":"1601","description":"Asset account, default 1601.","type":"string"},"input_tax_account_code":{"default":"1284","description":"Input tax account, default 1284. The VAT return reads the period movement of this account.","type":"string"},"memo":{"default":"","description":"Note on the register and on the voucher.","type":"string"},"name":{"description":"What was bought, as it should read on the register.","type":"string"},"origin_voucher_no":{"default":null,"description":"An existing voucher that already carries this purchase.","type":["string","null"]},"paid_from_account_code":{"default":null,"description":"Which account the money left, e.g. 1102 銀行存款. Writes the acquisition voucher. Bought on credit, leave this out, enter the supplier's bill on the payables screen with 1601 as its debit account, and give that bill's voucher as `origin_voucher_no`.","type":["string","null"]},"tax_amount":{"default":null,"description":"Deductible input tax. Left out it follows the VAT rules in force on the acquisition date; send `0` for a purchase that carries none.","type":["string","null"]}},"required":["category","cost","name"],"title":"CreateFixedAssetInput","type":"object"},
