  'submit_expense_claim': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"amount":{"description":"Amount, tax inclusive.","type":"string"},"claimant":{"default":null,"description":"Claimant. Defaults to the current actor.","type":["string","null"]},"dept_code":{"default":null,"description":"Department code.","type":["string","null"]},"document_no":{"default":null,"description":"Document number of the receipt (upload it with upload_document first).","type":["string","null"]},"memo":{"default":null,"type":["string","null"]},"pay_method":{"default":null,"description":"`reimburse` paid with the month-end run (default), or `petty_cash` paid immediately.","type":["string","null"]},"spent_on":{"default":null,"description":"Spend date (YYYY-MM-DD). Defaults to today.","format":"date","type":["string","null"]},"suggested_account_code":{"default":null,"description":"Expense account suggested by AI from the receipt. A person decides the final account at the accounting step.","type":["string","null"]},"title":{"description":"What the money was spent on.","type":"string"}},"required":["amount","title"],"title":"SubmitExpenseClaimInput","type":"object"},
