  'update_employee': {"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"EmployeeBankAccountInput":{"properties":{"account_no":{"description":"Account number.","type":"string"},"bank_name":{"default":"","description":"Bank and branch.","type":"string"},"is_payroll":{"default":false,"description":"Whether the monthly payroll transfer goes here. At most one account per person may be marked; when none is, the first one in the list is used.","type":"boolean"},"note":{"default":"","description":"What this account is for.","type":"string"}},"required":["account_no"],"type":"object"}},"properties":{"bank_accounts":{"description":"Every bank account kept for this person. Omit to leave the accounts on file alone; send the whole list to replace them.","items":{"$ref":"#/definitions/EmployeeBankAccountInput"},"type":["array","null"]},"base_salary":{"default":null,"description":"Base salary. Amounts are strings in JSON. Three states on update: omit to leave it alone, send `\"0\"` to clear it back to not-agreed-yet, send a number to change it. On create, omitting it means not agreed yet and payroll refuses this employee by name instead of paying nothing.","type":["string","null"]},"dept_code":{"default":null,"description":"Department dimension value code; only the department dimension is searched.","type":["string","null"]},"emp_no":{"default":"","description":"Employee number, e.g. `E001`. Leave blank when creating and the next `E###` is assigned; required when updating, because it is the key.","type":"string"},"employment_type":{"default":"full_time","description":"One of `full_time`, `part_time`, `contract`.","type":"string"},"health_insured_salary":{"default":null,"description":"Health insurance salary as filed with the authorities; kept as given, never corrected against a ruleset. Three states, as `base_salary`.","type":["string","null"]},"hired_on":{"description":"Hire date.","format":"date","type":"string"},"id_no":{"default":"","description":"National ID, one letter followed by nine digits, checksum included. May be blank while it has not been collected.","type":"string"},"labor_insured_salary":{"default":null,"description":"Labour insurance salary as filed with the authorities; kept as given, never corrected against a ruleset. Three states, as `base_salary`.","type":["string","null"]},"left_on":{"default":null,"description":"Planned or actual leaving date. Required when status is leaving or left.","format":"date","type":["string","null"]},"name":{"description":"Name.","type":"string"},"note":{"default":"","description":"Notes.","type":"string"},"pension_wage":{"default":null,"description":"Pension contribution wage as filed with the authorities; kept as given, never corrected against a ruleset. Three states, as `base_salary`.","type":["string","null"]},"status":{"default":"active","description":"One of `active`, `leaving`, `left`.","type":"string"},"title":{"default":"","description":"Job title.","type":"string"}},"required":["hired_on","name"],"title":"EmployeeInput","type":"object"},
  'create_bank_account': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"account_no":{"description":"Bank account number.","type":"string"},"gl_code":{"description":"Required GL account; must be an active, postable asset account.","type":"string"},"name":{"description":"Account name.","type":"string"},"sort_order":{"default":0,"description":"Display order.","format":"int32","type":"integer"}},"required":["account_no","gl_code","name"],"title":"CreateBankAccountInput","type":"object"},
  'create_dimension_value': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"active":{"default":true,"description":"Whether it is active.","type":"boolean"},"code":{"default":"","description":"Dimension value code. Empty means the display name; it is only a lookup key for `dept_code` and every screen picks values by label.","type":"string"},"dimension_code":{"description":"Existing dimension code; this operation does not create dimensions.","type":"string"},"label":{"description":"Display name.","type":"string"},"sort_order":{"default":0,"description":"Display order.","format":"int32","type":"integer"}},"required":["dimension_code","label"],"title":"CreateDimensionValueInput","type":"object"},
  'update_dimension_value': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"active":{"default":null,"description":"Whether it stays selectable. Omit to leave it.","type":["boolean","null"]},"code":{"description":"Code of the value to update.","type":"string"},"dimension_code":{"description":"Existing dimension code.","type":"string"},"label":{"default":null,"description":"New display name. Omit to leave it.","type":["string","null"]}},"required":["code","dimension_code"],"title":"UpdateDimensionValueInput","type":"object"},
  'set_approval_rule': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"condition_note":{"default":"","description":"Description of the condition.","type":"string"},"delete":{"default":false,"description":"true deletes this step; a flow always keeps at least one.","type":"boolean"},"label":{"default":null,"description":"Step name. May be omitted when deleting.","type":["string","null"]},"min_amount":{"default":null,"description":"Company policy amount threshold; null means always required. Amounts are strings in JSON.","type":["string","null"]},"role_code":{"default":null,"description":"Responsible role. null is allowed for a step the claimant handles.","type":["string","null"]},"step_no":{"description":"Step number, also the upsert key.","format":"int32","type":"integer"}},"required":["step_no"],"title":"SetApprovalRuleInput","type":"object"},
