  'set_company_timezone': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"offset":{"description":"Hours and minutes east of UTC, as `+08:00` or `-05:30`.","type":"string"}},"required":["offset"],"title":"SetCompanyTimezoneInput","type":"object"},
  'list_chart_of_accounts': {"$schema":"http://json-schema.org/draft-07/schema#","properties":{"only_used":{"default":false,"description":"List only accounts actually used in this period. All by default.","type":"boolean"}},"title":"ListChartOfAccountsInput","type":"object"},
